import numpy as np

def floyd_warshall(adjacency_matrix):
    """
    Implement the Floyd-Warshall algorithm to find the shortest path distances between every pair of nodes in a weighted, directed graph.

    :param adjacency_matrix: List of lists representing the edge weights between respective nodes.
    :return: A list of lists containing the shortest distance between each pair of nodes.
    """
    n = len(adjacency_matrix)
    # Copy the adjacency matrix to avoid modifying the input data
    dist = np.array(adjacency_matrix)

    # Initialize the distance matrix with itself and infinity for unreachable paths
    for i in range(n):
        for j in range(n):
            if i == j:
                dist[i][j] = 0
            elif dist[i][j] == float('inf'):
                dist[i][j] = np.inf

    # Apply Floyd-Warshall algorithm
    for k in range(n):
        for i in range(n):
            for j in range(n):
                dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j])

    return dist.tolist()

